{
  "session_id": "s_cf87a82f",
  "request_id": "r_2c8a12683b4f",
  "expected_revision": 1,
  "action_mode": "result",
  "player_input": "我四处看看",
  "player_authorized": false,
  "operations": [
    {
      "op": "add_fact",
      "key": "sun_shaotang.request.copy_manuscript",
      "text": "孙绍棠在排字房求钱采薇今晚替他誊一份手稿，赶在天亮前送到报馆",
      "visibility": "private",
      "known_by": ["player", "column_writer"],
      "origin": "observed"
    },
    {
      "op": "add_fact",
      "key": "composing_room.proof.extra_char",
      "text": "今夜副刊校样上多了一个原稿里没有的铅字",
      "visibility": "private",
      "known_by": ["player"],
      "origin": "observed"
    },
    {
      "op": "npc_action",
      "npc_id": "column_writer",
      "action": "顺着钱采薇的视线警觉地收回手，退后半步，朝铅字架后的夹道递了个眼色",
      "significant": false
    },
    {
      "op": "npc_action",
      "npc_id": "teahouse_keeper",
      "action": "把紫砂小壶搁在桌角，目光扫过副刊校样，随口提起十二点后过河浜石桥要通行条",
      "significant": false
    },
    {
      "op": "npc_state",
      "npc_id": "column_writer",
      "mood": "焦急防备"
    },
    {
      "op": "npc_state",
      "npc_id": "teahouse_keeper",
      "mood": "不动声色"
    },
    {
      "op": "advance_time",
      "minutes": 5
    }
  ],
  "content_tags": ["workplace"],
  "summary": "钱采薇没有立刻应承孙绍棠，先环顾排字房四周，察看各处动静与手头校样。",
  "open_action": "孙绍棠朝铅字架后的夹道递眼色等你过去，程砚农将茶壶搁在桌角尚未离开",
  "quotes": [
    "今晚雨大，过了十二点再想过河浜石桥，可得凭通行条了。"
  ]
}

{
  "session_id": "s_cd49a28c",
  "request_id": "r_2b5fcfef4b35",
  "expected_revision": 1,
  "action_mode": "attempt",
  "player_input": "我在街上随便逛逛",
  "player_authorized": true,
  "acts_on": ["wine_mistress", "bailiff"],
  "operations": [
    {
      "op": "npc_response",
      "npc_id": "bailiff",
      "response": "refuse",
      "note": "坊门已闭宵禁生效，无正当由头不得在街上乱逛，横刀拦阻盘查"
    },
    {
      "op": "npc_response",
      "npc_id": "wine_mistress",
      "response": "partial",
      "note": "见不良帅拦阻，借机打圆场劝崔绿珠留步饮酒避开街面盘查"
    },
    {
      "op": "npc_action",
      "npc_id": "bailiff",
      "action": "横刀微抬挡在雅室门前，目光冷峻地盯着崔绿珠，提醒夜禁已至且金吾卫正严查街面",
      "significant": false
    },
    {
      "op": "npc_action",
      "npc_id": "wine_mistress",
      "action": "笑着伸手按在崔绿珠案头的字纸旁，提醒外面巡丁正多，不如在楼上雅室暂避",
      "significant": false
    },
    {
      "op": "advance_time",
      "minutes": 5
    }
  ],
  "content_tags": ["workplace"],
  "summary": "崔绿珠欲离席上街闲逛，被守在门前的不良帅裴子昂持刀依法拦下，李景澄顺势劝其留宿雅室。",
  "open_action": "裴子昂横刀挡在珠帘外等崔绿珠退回，李景澄含笑递过斟满的酒盏",
  "quotes": [
    "暮鼓六百下早敲完了，外头金吾骑兵正在街面上巡，崔娘子眼下出去，可吃得消这四十板子？"
  ]
}

